[ "$BAD_CHECKS" -eq 0 ] || { echo "SHEPHERD FAILED: $BAD_CHECKS non-exempt checks are not successful"; exit 1; }
echo 'final_rest_gates=passed'","description":"Verify final PR gates","initial_wait":30,"mode":"sync"}

